		"Honeypot triggered." => "Honeypot activado.",
		"Submitted too quickly or the form expired. Please wait a few seconds and try again." => "Envío demasiado rápido o formulario caducado. Espere unos segundos e inténtelo de nuevo.",
		"Too many submissions from your IP address. Please try again later." => "Demasiados envíos desde su dirección IP. Vuelva a intentarlo más tarde.",
		"Submission flagged as spam by cloud filter." => "Envío marcado como spam por el filtro en la nube.",
		"Submission contains too many links." => "El envío contiene demasiados enlaces.",
