		"Possible N+1: this pattern repeated %1\$d times (%2\$s ms total) — %3\$s" => "Posible N+1: este patrón se repitió %1\$d veces (%2\$s ms en total) — %3\$s",
		"Origin detection" => "Detección de origen",
