		"Queue finished." => "Cola terminada.",
		"Queue cancelled." => "Cola cancelada.",
		"%1\$s already had a redirect — skipped. %2\$d path(s) remaining in the queue." => "%1\$s ya tenía una redirección — omitida. Quedan %2\$d ruta(s) en la cola.",
		"%1\$s already had a redirect — skipped. Queue finished." => "%1\$s ya tenía una redirección — omitida. Cola terminada.",
		"Create a 410 (Gone) rule for each of the %1\$d selected URL(s)?" => "¿Crear una regla 410 (Gone) para cada una de las %1\$d URL(s) seleccionada(s)?",
		"Create a 301 redirect to the target for each of the %1\$d selected URL(s)?" => "¿Crear una redirección 301 al destino para cada una de las %1\$d URL(s) seleccionada(s)?",
		"Enter a target URL or path first." => "Introduce primero una URL o ruta de destino.",
		"Create one rule that answers 410 (Gone) for everything under %1\$s?" => "¿Crear una sola regla que responda 410 (Gone) para todo lo que cuelga de %1\$s?",
		"No redirects selected." => "No hay ninguna redirección seleccionada.",
		"Select at least one redirect rule." => "Selecciona al menos una regla de redirección.",
		"Delete the %1\$d selected redirect rule(s)? This cannot be undone." => "¿Eliminar las %1\$d regla(s) de redirección seleccionada(s)? No se puede deshacer.",
		"%d redirect deleted.\x00%d redirects deleted." => "%d redirección eliminada.\x00%d redirecciones eliminadas.",
		"Rules are checked from top to bottom and the first match wins. Use the arrows to change the order; they are available while the list is unfiltered and in evaluation order." => "Las reglas se comprueban de arriba abajo y gana la primera que coincide. Usa las flechas para cambiar el orden; solo están disponibles mientras la lista no está filtrada y está en orden de evaluación.",
		"Search source or target…" => "Buscar por origen o destino…",
		"Search redirect rules" => "Buscar reglas de redirección",
		"Filter rules" => "Filtrar reglas",
		"All rules" => "Todas las reglas",
		"410 / 451 (Gone)" => "410 / 451 (Gone)",
		"Redirects (3xx)" => "Redirecciones (3xx)",
		"Wildcard / regex rules" => "Reglas wildcard / regex",
		"Sort rules" => "Ordenar reglas",
		"Evaluation order" => "Orden de evaluación",
		"Most visits" => "Más visitas",
		"Fewest visits" => "Menos visitas",
		"Most recent visit" => "Visita más reciente",
		"Oldest or never visited" => "Más antiguas o nunca visitadas",
